-- Default Indian e-commerce category tree for the businesses that existed before every business got one at sign-up.
-- Idempotent and tenant-scoped: a category that already exists (same slug, or same name under the same parent) is skipped, never renamed or duplicated.
-- Generated from packages/database/src/default-categories.ts. (FORCE ROW LEVEL SECURITY: system scope for the backfill, cleared after.)
SELECT set_config('app.scope', 'system', false);--> statement-breakpoint
INSERT INTO "categories" ("vendor_id", "parent_id", "name", "slug", "path", "sort_order")
SELECT v."id", NULL, d.name, d.slug, d.slug, d.ord
FROM "vendors" v
CROSS JOIN (VALUES ('Fashion', 'fashion', 1), ('Electronics', 'electronics', 2), ('Home & Kitchen', 'home-kitchen', 3), ('Beauty & Personal Care', 'beauty-personal-care', 4), ('Health & Wellness', 'health-wellness', 5), ('Grocery & Gourmet', 'grocery-gourmet', 6), ('Toys & Games', 'toys-games', 7), ('Sports & Outdoors', 'sports-outdoors', 8), ('Books & Stationery', 'books-stationery', 9), ('Automotive', 'automotive', 10), ('Pet Supplies', 'pet-supplies', 11), ('Baby', 'baby', 12), ('Tools & Hardware', 'tools-hardware', 13), ('Office Products', 'office-products', 14), ('Industrial & Scientific', 'industrial-scientific', 15)) AS d(name, slug, ord)
WHERE v."deleted_at" IS NULL
  AND NOT EXISTS (SELECT 1 FROM "categories" c WHERE c."vendor_id" = v."id" AND c."deleted_at" IS NULL AND (c."slug" = d.slug OR (c."parent_id" IS NULL AND lower(c."name") = lower(d.name))));--> statement-breakpoint
INSERT INTO "categories" ("vendor_id", "parent_id", "name", "slug", "path", "sort_order")
SELECT p."vendor_id", p."id", d.name, d.slug, p."path" || '/' || d.slug, d.ord
FROM "categories" p
JOIN (VALUES ('fashion', 'Men''s Clothing', 'mens-clothing', 1), ('fashion', 'Women''s Clothing', 'womens-clothing', 2), ('fashion', 'Kids'' Clothing', 'kids-clothing', 3), ('fashion', 'Footwear', 'footwear', 4), ('fashion', 'Bags & Luggage', 'bags-luggage', 5), ('fashion', 'Watches', 'watches', 6), ('fashion', 'Jewellery & Accessories', 'jewellery-accessories', 7), ('electronics', 'Mobiles & Accessories', 'mobiles-accessories', 1), ('electronics', 'Laptops & Computers', 'laptops-computers', 2), ('electronics', 'Audio & Headphones', 'audio-headphones', 3), ('electronics', 'Cameras & Photography', 'cameras-photography', 4), ('electronics', 'Smart Home', 'smart-home', 5), ('electronics', 'Wearables', 'wearables', 6), ('home-kitchen', 'Furniture', 'furniture', 1), ('home-kitchen', 'Home Decor', 'home-decor', 2), ('home-kitchen', 'Kitchen & Dining', 'kitchen-dining', 3), ('home-kitchen', 'Storage & Organisation', 'storage-organisation', 4), ('home-kitchen', 'Bedding & Linen', 'bedding-linen', 5), ('beauty-personal-care', 'Skincare', 'skincare', 1), ('beauty-personal-care', 'Haircare', 'haircare', 2), ('beauty-personal-care', 'Makeup', 'makeup', 3), ('beauty-personal-care', 'Fragrances', 'fragrances', 4), ('beauty-personal-care', 'Bath & Body', 'bath-body', 5), ('health-wellness', 'Vitamins & Supplements', 'vitamins-supplements', 1), ('health-wellness', 'Fitness Equipment', 'fitness-equipment', 2), ('health-wellness', 'Healthcare Devices', 'healthcare-devices', 3), ('grocery-gourmet', 'Staples & Grains', 'staples-grains', 1), ('grocery-gourmet', 'Snacks & Beverages', 'snacks-beverages', 2), ('grocery-gourmet', 'Spices & Condiments', 'spices-condiments', 3), ('toys-games', 'Toys', 'toys', 1), ('toys-games', 'Board Games & Puzzles', 'board-games-puzzles', 2), ('sports-outdoors', 'Sports Equipment', 'sports-equipment', 1), ('sports-outdoors', 'Outdoor & Camping', 'outdoor-camping', 2), ('books-stationery', 'Books', 'books', 1), ('books-stationery', 'Stationery & Craft', 'stationery-craft', 2), ('automotive', 'Car Accessories', 'car-accessories', 1), ('automotive', 'Bike Accessories', 'bike-accessories', 2), ('pet-supplies', 'Pet Food', 'pet-food', 1), ('pet-supplies', 'Pet Accessories', 'pet-accessories', 2), ('baby', 'Baby Care', 'baby-care', 1), ('baby', 'Baby Gear', 'baby-gear', 2), ('tools-hardware', 'Hand Tools', 'hand-tools', 1), ('tools-hardware', 'Power Tools', 'power-tools', 2), ('office-products', 'Office Furniture', 'office-furniture', 1), ('office-products', 'Office Supplies', 'office-supplies', 2), ('industrial-scientific', 'Industrial Supplies', 'industrial-supplies', 1), ('industrial-scientific', 'Lab & Scientific', 'lab-scientific', 2)) AS d(parent_slug, name, slug, ord) ON p."slug" = d.parent_slug
WHERE p."deleted_at" IS NULL
  AND NOT EXISTS (SELECT 1 FROM "categories" c WHERE c."vendor_id" = p."vendor_id" AND c."deleted_at" IS NULL AND (c."slug" = d.slug OR (c."parent_id" = p."id" AND lower(c."name") = lower(d.name))));--> statement-breakpoint
SELECT set_config('app.scope', '', false);
